// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        // pick a target block t such that blockhash(t-1) is known and within the 256-block window
        t = bound(t, 2, 200);
        vm.assume(actor != address(0) && actor != address(c));

        // go past block t so blockhash(t - 1) becomes readable
        vm.roll(t + 1);
        bytes32 bh = blockhash(t - 1);
        vm.assume(bh != bytes32(0));

        // roll back to block t - 2: locking here sets the target to t - 1's successor (t)
        // actually locking at block t - 2 stores target = t - 1... we instead lock at t - 1
        vm.roll(t - 1);
        bytes32 winningHash = keccak256(abi.encodePacked(bh)); // answer for target block t

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningHash);

        // move strictly past the stored target block (t)
        vm.roll(t + 1);
        c.settle();

        // Rule: a correct guess always pays out the 2-ether prize, leaving 1 ether.
        // The mutant loses the stored hash (guess stays 0 != winningHash), so it never pays.
        assertTrue(address(c).balance == 1 ether);
    }
}

