// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 baseBlock) public {
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        baseBlock = bound(baseBlock, 2, 1e12);

        // discover the future block's hash first (roll forward, read, roll back)
        vm.roll(baseBlock + 2);
        bytes32 bh = blockhash(baseBlock + 1);
        vm.assume(bh != bytes32(0));
        vm.roll(baseBlock);

        bytes32 winning = keccak256(abi.encodePacked(bh));

        // pre-fund c with a second 1-ether lock so the 2-ether transfer can succeed
        vm.deal(address(this), 2 ether);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(1)));

        // actor locks the winning hash for target block baseBlock + 1
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winning);

        // settle after the target block
        vm.roll(baseBlock + 3);
        vm.prank(actor);
        c.settle();

        // general rule: a correct lock of the winning hash always wins on settle,
        // paying out 2 ether and leaving c empty; the mutant stores bytes32(0),
        // never wins, and c keeps its 2 ether.
        assertTrue(address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        // keep the domain admissible and wide
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);
        vm.assume(h != bytes32(0)); // non-zero guess: exactly what the mutant cannot store

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(h) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever lockInGuess succeeds, the stored guess equals the supplied hash.
        assertTrue(!ok || (c.guesses(actor).guess == h && c.guesses(actor).block != 0));
    }
}

