pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(0) && actor != address(c));

        // player locks in a guess with the fuzzer-chosen hash
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // jump far past the target block so blockhash(target) reads as 0,
        // hence answer == keccak256(abi.encodePacked(bytes32(0)))
        vm.roll(block.number + 300);

        vm.prank(actor);
        c.settle();

        // General rule: a locked guess of bytes32(0) can NEVER win the payout,
        // so the contract must still hold all 3 ether after settle.
        assertTrue(
            h != bytes32(0) || address(c).balance == 3 ether,
            "guess bytes32(0) must never win the 2 ether payout"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 lockBlock, address actor) public {
        vm.assume(lockBlock > 0 && lockBlock < type(uint64).max);
        vm.assume(actor != address(0) && actor != address(c));

        // The target blockhash is aged out (settle happens 257 blocks after the
        // target block), so blockhash(target) == bytes32(0) and the correct
        // answer is keccak256(bytes32(0)). A player who locks in exactly this
        // value is a legitimate winner.
        bytes32 winningGuess = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 1 ether);
        vm.roll(lockBlock);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningGuess);

        // Move past the 256-block blockhash window so the answer is keccak256(bytes32(0)).
        vm.roll(lockBlock + 258);
        vm.prank(actor);
        c.settle();

        // Rule: a winning guess always drains the prize from the contract.
        assertTrue(address(c).balance == 0, "winning guess must pay out the prize");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function testLockIn(uint256 amount) public {
        require(amount == 1 ether);
        require(address(this).balance >= amount);
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.lockInGuess.selector, keccak256(abi.encodePacked(uint256(1))))
        );
        assert(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, bytes32 guess) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(guess) { reverted = false; } catch { reverted = true; }
        assert(reverted == (amount != 1 ether));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, bytes32 guess) public payable {
        require(address(this).balance >= amount);
        bool revertedFirst;
        try c.lockInGuess{value: amount}(guess) { revertedFirst = false; } catch { revertedFirst = true; }
        bool revertedSecond;
        require(address(this).balance >= amount);
        try c.lockInGuess{value: amount}(guess) { revertedSecond = false; } catch { revertedSecond = true; }
        assert(amount == 1 ether ? (!revertedFirst || revertedSecond) : (revertedFirst || !revertedSecond));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 hash, uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(hash) { reverted = false; } catch { reverted = true; }
        assert(!reverted && address(c).balance == 2 * amount);
    }
    receive() external payable {}
}
